import React, { useEffect, useState } from 'react'
import { fetchPokemons } from '../data/pokemonData' // Import fetchPokemons function

function RandomPokemonImage() {
  const DAILY_KEY = 'dailyPokemon'
  const [imagePath, setImagePath] = useState('')

  useEffect(() => {
    const storedData = JSON.parse(localStorage.getItem(DAILY_KEY))

    if (storedData && isToday(storedData.date)) {
      setImagePath(storedData.imagePath)
    } else {
      fetchRandomPokemon()
    }
  }, [])

  const isToday = (dateString) => {
    const today = new Date().toDateString()
    const storedDate = new Date(dateString).toDateString()
    return today === storedDate
  }

  const fetchRandomPokemon = async () => {
    try {
      // Use the fetchPokemons function to get the data
      const data = await fetchPokemons()

      if (data && data.length > 0) {
        const randomPokemon = data[Math.floor(Math.random() * data.length)]
        console.log('Randomly Selected Pokémon:', randomPokemon) // Log selected Pokémon

        const imageUrl = randomPokemon.imageUrl.replace('../', '/')
        const pokemonData = {
          imagePath: imageUrl,
          date: new Date().toISOString(),
        }

        localStorage.setItem(DAILY_KEY, JSON.stringify(pokemonData))
        setImagePath(imageUrl)
      }
    } catch (error) {
      console.error('Error fetching Pokémon:', error)
    }
  }

  return (
    <div className='p-8'>
      {imagePath && (
        <div className='mx-auto w-40 h-40'>
          <img
            src={imagePath}
            alt='Random Pokémon'
            className='mx-auto w-40 h-40 object-cover mb-4'
          />
        </div>
      )}
    </div>
  )
}

export default RandomPokemonImage
